(()=>{
 const desktop=window.orbitDesktop;if(!desktop?.claimWelcome||['#pdf','#browser'].includes(location.hash))return;
 let dialog=null;
 function close(immediate=false){if(!dialog)return;const current=dialog;dialog=null;if(immediate||matchMedia('(prefers-reduced-motion: reduce)').matches){current.close();current.remove();return;}current.classList.add('leaving');setTimeout(()=>{current.close();current.remove();},220);}
 desktop.onOpenPage?.(page=>{if(page?.url||['pdf','browser'].includes(page?.id))close(true);});window.addEventListener('hashchange',()=>{if(location.hash&&location.hash!=='#overview')close(true);});
 desktop.claimWelcome().then(result=>{
  if(!result.ok||!result.show||['#pdf','#browser'].includes(location.hash))return;
  const en=result.language!=='zh',copy=en?{title:'Welcome to Orbit.',subtitle:'A calmer space for your day.',start:'Get started',close:'Close',features:[['Read with ChatGPT.','Keep your PDF beside ChatGPT, with automatic PDF attachment and a resizable split.'],['Your day, at a glance.','Optional Gmail and Calendar summaries, local plans and meeting reminders on one home screen.'],['A workspace you can shape.','Pin and categorize workspaces, save text/image favorites, and use the optional local API / MCP bridge.']]}:{title:'欢迎来到 Orbit。',subtitle:'更从容的空间，让每一天更专注。',start:'开始使用',close:'关闭',features:[['与 ChatGPT 一起阅读。','PDF 与 ChatGPT 并排阅读，自动附加当前 PDF，自由调整分屏宽度。'],['一天安排，一目了然。','在一个主页查看可选的 Gmail 与日历摘要、本地计划和会议提醒。'],['由你塑造的工作空间。','置顶与分类工作台，收藏文字和图片，并可选用本地 API / MCP 桥接。']]};
  dialog=document.createElement('dialog');dialog.id='orbit-welcome';dialog.dataset.userContent='';dialog.lang=en?'en':'zh-CN';dialog.setAttribute('aria-labelledby','welcome-title');dialog.innerHTML='<button class="welcome-close" type="button">×</button><div class="welcome-inner"><img class="welcome-mark" src="assets/welcome-logo.png" alt=""><h1 id="welcome-title"></h1><p class="welcome-subtitle"></p><div class="welcome-features"></div><button class="welcome-start" type="button"></button></div>';
  dialog.querySelector('h1').textContent=copy.title;dialog.querySelector('.welcome-subtitle').textContent=copy.subtitle;const closeButton=dialog.querySelector('.welcome-close');closeButton.title=copy.close;closeButton.setAttribute('aria-label',copy.close);closeButton.onclick=()=>close();
  copy.features.forEach(([title,description],i)=>{const card=document.createElement('article');card.style.setProperty('--order',i);const number=document.createElement('span'),heading=document.createElement('h2'),body=document.createElement('p');number.className='welcome-number';number.textContent='0'+(i+1);heading.textContent=title;body.textContent=description;card.append(number,heading,body);dialog.querySelector('.welcome-features').append(card);});
  const start=dialog.querySelector('.welcome-start');start.textContent=copy.start;start.onclick=()=>close();dialog.addEventListener('cancel',event=>{event.preventDefault();close(true);});document.body.append(dialog);dialog.showModal();start.focus({preventScroll:true});
 }).catch(()=>{});
})();
